#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
Embed the welcome / setup page (setup.htm) into the firmware.

Not part of the firmware build. Standard library only. Run by hand after
editing setup.htm, then rebuild the firmware:

    python gen_setup_page.py

The page is gzip-compressed and written as a byte array to
../asl_setup_page.h, which the usermod serves at /setup with
"Content-Encoding: gzip". It lives in the firmware (not the file system) so
it also works on a freshly flashed board whose file system is empty.
"""

import gzip
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, 'setup.htm')
OUT = os.path.join(HERE, '..', 'asl_setup_page.h')


def main():
  raw = open(SRC, 'rb').read()
  gz = gzip.compress(raw, compresslevel=9, mtime=0)   # mtime=0: same input -> same header
  lines = []
  for i in range(0, len(gz), 20):
    lines.append('  ' + ', '.join(f'0x{b:02x}' for b in gz[i:i + 20]) + ',')
  out = (
    '// Generated by web/gen_setup_page.py from web/setup.htm - do not edit;\n'
    '// edit setup.htm and rerun the script instead.\n'
    '#pragma once\n'
    '#include <Arduino.h>\n\n'
    f'static const size_t ASL_SETUP_PAGE_LEN = {len(gz)};   // gzip; {len(raw)} bytes uncompressed\n'
    'static const uint8_t ASL_SETUP_PAGE[] PROGMEM = {\n'
    + '\n'.join(lines) + '\n};\n'
  )
  open(OUT, 'w', encoding='utf-8', newline='\n').write(out)
  print(f'wrote {os.path.basename(OUT)}: {len(raw)} bytes -> {len(gz)} bytes gzip')


if __name__ == '__main__':
  main()
# AI: end
